delete from MAM_GP_BATCH_GRP_DEF WHERE GP_BATCH_GRP_CD LIKE 'MA%';



delete from FCM_MENU WHERE MENU_ID LIKE 'MA%' AND PARENT_MENU_ID = 'MCF' ;

delete from FCM_MENU WHERE PARENT_MENU_ID LIKE 'MCF,MA%' AND MENU_ID NOT LIKE 'MB%' AND MENU_ID NOT LIKE 'P%' ;


delete from FCM_MENU_ARGS WHERE MENU_ID LIKE 'MA%' AND PARENT_MENU_ID LIKE 'MCF,MA%';

delete from FCM_MENU_NM WHERE MENU_ID LIKE 'MA%';
